from pathlib import Path
import sqlite3, uuid
ROOT=Path(__file__).resolve().parents[1]; DB=ROOT/"data"/"procuralens.db"; DB.parent.mkdir(parents=True,exist_ok=True)
con=sqlite3.connect(DB); con.execute("PRAGMA foreign_keys=ON")
con.executescript("""
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,reference TEXT,description TEXT,category TEXT,owner TEXT,evaluation_date TEXT,currency TEXT,notes TEXT,blind_mode INTEGER DEFAULT 0,status TEXT DEFAULT 'Draft',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS criteria(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT,area TEXT NOT NULL,weight REAL NOT NULL,max_score REAL NOT NULL,min_score REAL DEFAULT 0,guidance TEXT,critical INTEGER DEFAULT 0,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS knockout_rules(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL,name TEXT NOT NULL,question TEXT NOT NULL,expected TEXT NOT NULL,area TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,name TEXT NOT NULL,alias TEXT,submission_date TEXT NOT NULL,experience REAL NOT NULL,notes TEXT,document_name TEXT,document_hash TEXT,pages INTEGER,extracted_text TEXT);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,created_at TEXT NOT NULL,completed_at TEXT,mode TEXT,provider TEXT,model TEXT,status TEXT,criteria_snapshot TEXT,warning_json TEXT DEFAULT '[]',export_json TEXT);
CREATE TABLE IF NOT EXISTS ai_scores(id INTEGER PRIMARY KEY AUTOINCREMENT,run_id TEXT NOT NULL,supplier_id TEXT NOT NULL,criterion_id INTEGER NOT NULL,proposed_score REAL NOT NULL,max_score REAL NOT NULL,justification TEXT,strengths_json TEXT,gaps_json TEXT,missing_json TEXT,references_json TEXT,confidence REAL,requires_review INTEGER DEFAULT 0,warnings_json TEXT DEFAULT '[]',UNIQUE(run_id,supplier_id,criterion_id));
CREATE TABLE IF NOT EXISTS sme_reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,run_id TEXT NOT NULL,supplier_id TEXT NOT NULL,criterion_id INTEGER NOT NULL,reviewer TEXT NOT NULL,area TEXT NOT NULL,reviewed_score REAL NOT NULL,reason TEXT,comment TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS final_approvals(id INTEGER PRIMARY KEY AUTOINCREMENT,run_id TEXT NOT NULL,supplier_id TEXT NOT NULL,criterion_id INTEGER NOT NULL,approver TEXT NOT NULL,approved_score REAL NOT NULL,rationale TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knockout_results(id INTEGER PRIMARY KEY AUTOINCREMENT,run_id TEXT NOT NULL,supplier_id TEXT NOT NULL,rule_id INTEGER NOT NULL,ai_result TEXT NOT NULL,reasoning TEXT,references_json TEXT,reviewer TEXT,reviewer_decision TEXT,reviewer_comment TEXT,reviewed_at TEXT,UNIQUE(run_id,supplier_id,rule_id));
CREATE TABLE IF NOT EXISTS feedback_examples(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT,criterion_name TEXT,ai_score REAL,final_score REAL,reason TEXT,comment TEXT,approved INTEGER DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT,run_id TEXT,event_type TEXT,detail TEXT,created_at TEXT NOT NULL);
""")
pid="demo-project"
con.execute("INSERT OR IGNORE INTO projects(id,name,reference,description,category,owner,evaluation_date,currency,notes,blind_mode,status,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,datetime('now'))",(pid,"Enterprise IT Services RFP","RFP-2026-014","Seeded ProcureLens classroom project","IT Services","Procurement Evaluation Team","2026-11-01","INR","Bundled demo project",0,"Draft"))
criteria=[("Technical Capability","Architecture, integrations, scalability, technical fit","IT",30,10,5,0),("Implementation Plan","Timeline, milestones, staffing, risk plan","IT",20,10,5,0),("Commercial Value","Pricing clarity, total cost, assumptions","Finance",20,10,5,0),("Security & Compliance","Controls, certifications, privacy, auditability","Security",20,10,6,1),("Support & Experience","Support model, similar projects, references","Procurement",10,10,5,0)]
for n,d,a,w,m,mi,c in criteria: con.execute("INSERT INTO criteria(project_id,name,description,area,weight,max_score,min_score,guidance,critical,active) SELECT ?,?,?,?,?,?,?,?, ?,1 WHERE NOT EXISTS(SELECT 1 FROM criteria WHERE project_id=? AND name=?)",(pid,n,d,a,w,m,mi,"0 no answer; 5 meets; 10 exceptional",c,pid,n))
rules=[("Information security certification","Does the supplier provide an accepted security certification?","ISO 27001 or accepted equivalent","Security"),("Data residency","Can production data, backups, and logs remain in India?","Yes, with explicit evidence","Legal"),("Maximum budget","Is the committed price within budget?","Within approved budget","Finance"),("Required implementation date","Can the supplier go live within 26 weeks?","Yes","IT")]
for n,q,e,a in rules: con.execute("INSERT INTO knockout_rules(project_id,name,question,expected,area) SELECT ?,?,?,?,? WHERE NOT EXISTS(SELECT 1 FROM knockout_rules WHERE project_id=? AND name=?)",(pid,n,q,e,a,pid,n))
con.commit(); con.close(); print(f"Created and seeded {DB}")
